def run_record(spark: SparkSession, run_id: str, rows: int, status: str, error_message: str | None) -> DataFrame:
    """One run log row."""
    schema = T.StructType([
        T.StructField("run_id", T.StringType(), False),
        T.StructField("rows_processed", T.LongType(), False),
        T.StructField("status", T.StringType(), False),
        T.StructField("error_message", T.StringType(), True),
    ])
    return spark.createDataFrame([(run_id, rows, status, error_message)], schema)
